		{
			title = "{npc:12736}",
			when = { { k = "dungeon", map = 48, name = "Blackfathom Deeps" } },
			note = "For your {area:2797} run, in the same tunnels as the Sapphires: {npc:12736}'s ruins errand. Look for a group now if you have none yet.",
			goals = {
				{ t = "accept", minLevel = 21, quest = 6921, npc = 12736, map = 1440, x = 11.52, y = 34.3, z = 6, group = { map = 48, kind = "dungeon", name = "Blackfathom Deeps" }, qlvl = 27 },
			},
		},
		{
			title = "{area:2797} ruins",
			note = "The way to the Sapphires is through the sunken ruins at the north end of the strand: go down the stairs into the pit.",
			goals = {
				{ t = "goto", map = 1440, x = 14.5, y = 14.2, f = "e", text = "{area:2797} ruins" },
			},
		},
		{
			title = "Sapphires of Aku'Mai",
			note = "The Sapphires are blue crystals on the walls of the tunnels leading to the {area:2797} portal, underground and outside the instance: swim down from the pit, under the wall, into the cave. The satyrs and naga in the tunnels are elite: grouping up is advised. The crystals respawn quickly, so there is no need to go deep.",
			goals = {
				{ t = "collect", quest = 6563, item = 16784, count = 20, map = 1440, x = 13.59, y = 13.14, z = -16.1, f = "e", fromId = 178184, fromKind = "object", group = { kind = "elite", lvl = 22, near = true, rank = 1 }, oi = 1, spotsPacked = "12.9,13.22,-16.3,0;13.07,12.87,,0;13.17,13.49,,0;13.35,12.78,,0;13.45,12.56,,0;13.53,11.85,,0;13.59,13.14,-16.1,0;13.69,12.27,-11.4,0;13.73,10.61,,0;13.79,11.15,,0;13.84,11.79,,0" },
			},
		},
		{
			title = "{area:2797}",
			when = { { k = "dungeon", map = 48, name = "Blackfathom Deeps" }, { k = "onquest", q = { 6921 } } },
			note = "{area:2797} is a dungeon for a group of five, about levels 22 to 30, and a full run takes about an hour. Its portal is a little further along the tunnels you are in, past the Sapphires.\nInside: the {object:177964} lies under the water of the Moonshrine Ruins' pool, beneath the walkway (clear the crabs first): open it for the {item:16762}, and {quest:6922} comes; open the {item:16782} he drops for a quest for {npc:12736}. The Tide Priestesses sometimes drop a {item:16790}: open it for another quest for {npc:12736}. {npc:4787}, by a campfire in an underwater side room off Ghamoo-ra's room, offers Blackfathom Villainy ({npc:4832}' head, for {npc:9087} on {zone:1456}'s {area:1639}).",
			goals = {
				{ t = "enter", map = 1440, x = 14.5, y = 14.2, f = "e", area = 2797, location = "Blackfathom Deeps" },
				{ t = "complete", quest = 6921, note = "{quest:6921}: the {item:16762}, from the {object:177964}", group = { map = 48, kind = "dungeon", name = "Blackfathom Deeps" }, objs = { { count = 1, text = "Fathom Core" } } },
			},
		},
		{
			title = "{area:2301}",
